/bin/bash -lc "python - <<'PY'
import sim, mujoco, numpy as np
s=sim.Sim()
for i in range(s.model.nbody):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if nm: print(i,nm)
print('---sites---')
for i in range(s.model.nsite):
    nm=mujoco.mj_id2name(s.model,mujoco.mjtObj.mjOBJ_SITE,i)
    if nm: print(i,nm)
print('nbody',s.model.nbody,'nsite',s.model.nsite)
PY"

